def _build_component_06():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        rows = {name: {row["version"]: row for row in packages[name]}
                for name in names}
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        choices = [[None] + [row for row in packages[name]
                             if row["version"] not in blocked.get(name, []) and
                             (name not in pins or row["version"] == pins[name])]
                   for name in names]
        best_vector = None
        best = None

        for selected in product(*choices):
            installed = {name: row for name, row in zip(names, selected)
                         if row is not None}
            if any(name not in installed or not low <= installed[name]["version"] <= high
                   for name, (low, high) in roots.items()):
                continue
            # Derive the active closure and accumulate every constraint on each package.
            constraints = {}
            edges = {}
            pending = list(roots)
            seen_edges = set()
            valid = True
            while pending and valid:
                name = pending.pop()
                row = installed.get(name)
                if row is None:
                    valid = False
                    break
                edges.setdefault(name, [])
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    edges[name].append(target)
                    constraints.setdefault(target, []).append((dep["min"], dep["max"]))
                    if target not in seen_edges:
                        pending.append(target)
                        seen_edges.add(target)
            if not valid:
                continue
            closure = set(edges)
            if closure != set(installed):
                continue
            for name, ranges in constraints.items():
                version = installed[name]["version"]
                if any(not lo <= version <= hi for lo, hi in ranges):
                    valid = False
                    break
            if not valid:
                continue
            # Reject directed cycles, including self edges.
            active, done = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                if any(not visit(child) for child in edges.get(name, [])):
                    return False
                active.remove(name)
                done.add(name)
                return True
            if not all(visit(name) for name in closure):
                continue
            vector = tuple(installed[name]["version"] if name in installed else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector, best = vector, {name: row["version"]
                                             for name, row in installed.items()}
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _build_component_07():
    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        k = data["k"]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            # At most two half-open intervals may overlap.
            events = []
            for job in subset:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            feasible = True
            for _, delta in sorted(events):  # end (-1) precedes start (+1)
                active += delta
                if active > 2:
                    feasible = False
                    break
            if not feasible:
                continue
            value = sum(job["value"] for job in subset)
            selected_ids = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and selected_ids < best_ids)):
                best_value, best_ids = value, selected_ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    def solve(data):
        n = data["n"]
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(n)]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source, target = data["source"], data["target"]
        initial_mask = bit.get(source, 0)
        start_state = (source, initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == target and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, remaining - 1))
                for duration, next_remaining in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit.get(next_node, 0)
                    next_state = (next_node, next_mask, next_remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask,
                                              next_remaining))
        return {"arrival": None}
    return solve


